        ratio = self.rate(part, port.stream.timebase) / self.rate(
            child, self.output(child, port.binding.output).stream.timebase
        )
        return [
            e.model_copy(update={'tick': exact_tick(e.tick, ratio)}) for e in events
        ]
    return None
