Source code in <code>ufor/library_files.py</code> <pre><code>def score_files(
    root: Path,
    config: Path,
    library: str,
    diagnostics: list[Diagnostic],
    max_files: int,
) -&gt; list[Path]:
    files = []
    visited = 0

    def walk_error(error: OSError) -&gt; None:
        diagnostics.append(
            Diagnostic(library=library, address='/', code='io', message=str(error))
        )

    for directory, folders, names in root.walk(
        on_error=walk_error, follow_symlinks=False
    ):
        folders.sort()
        names.sort()
        for name in [*folders, *names]:
            visited += 1
            if visited &gt; MAX_DISCOVERY_ENTRIES:
                diagnostics.append(
                    Diagnostic(
                        library=library,
                        address='/',
                        code='limit',
                        message='library discovery exceeds 100000 entries',
                    )
                )
                return sorted(files, key=lambda p: p.relative_to(root).as_posix())
            file = directory / name
            try:
                symlink = file.is_symlink()
            except OSError as error:
                diagnostics.append(
                    Diagnostic(
                        library=library,
                        address='/' + file.relative_to(root).as_posix(),
                        code='io',
                        message=str(error),
                    )
                )
                continue
            if symlink:
                diagnostics.append(
                    Diagnostic(
                        library=library,
                        address='/' + file.relative_to(root).as_posix(),
                        code='symlink',
                        message='symlink skipped',
                    )
                )
            elif (
                name in names
                and file.suffix in ('.toml', '.py')
                and file.absolute() != config
            ):
                if len(files) &gt;= max_files:
                    diagnostics.append(
                        Diagnostic(
                            library=library,
                            address='/',
                            code='limit',
                            message='library exceeds max_files',
                        )
                    )
                    return sorted(files, key=lambda p: p.relative_to(root).as_posix())
                files.append(file)
    return sorted(files, key=lambda p: p.relative_to(root).as_posix())
