            slot_bounds = spatial_bounds(effective, target)
            low = instrument_bounds[0] + slot_bounds[0]
            high = instrument_bounds[1] + slot_bounds[1]
            if low &lt; -1 or high &gt; 1:
                raise ValueError(
                    f'Slot {slot.name}: combined {target} range [{low}, {high}] '
